-- Упражнения книги 17, глава 22 (oVirt). Файл строит scratchpad/ovirt/builder.py; после правок можно редактировать и вручную.
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'virt-sim-ovirt-sched', 0, 'lab', 'Симулятор: планировщик oVirt', 'Планировщик выбирает хост для запуска виртуальной машины в два шага: фильтры отбрасывают неподходящие хосты, веса ранжируют оставшиеся. В четырёх сценариях подберите политику кластера: включите нужные фильтры (память, сеть, антиаффинность) и расставьте веса (равномерная нагрузка, свободная память, упаковка). Машины запускаются по одной, каждая занимает место на выбранном хосте. Упражнение решено, когда цели всех сценариев выполнены.', '', 'Фильтры — жёсткие условия, веса — предпочтения. Без весов побеждает первый по имени хост. Равномерность и упаковка — противоположные веса, их не включают вместе. Нарушенное ограничение, которое политика не проверяла, считается ошибкой размещения.', '{}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-filter-hosts', 1, 'func', 'Фильтры планировщика', 'Фильтры отбрасывают хосты, на которых машину запустить нельзя. Хост подходит, если одновременно выполнены три условия: свободной памяти free_mb не меньше, чем mem_mb машины; ядер cores не меньше, чем vcpus машины; и все сети машины nets есть среди сетей хоста nets. Напишите функцию filter_hosts(hosts, vm): hosts — словарь имя → {"free_mb": число, "cores": число, "nets": список имён}, vm — {"mem_mb": число, "vcpus": число, "nets": список имён}. Верните отсортированный по имени список подходящих хостов.', 'def filter_hosts(hosts, vm):
    pass
', 'Для сетей удобно сравнить множества: set(vm[''nets'']) <= set(h[''nets'']).', '{"func": "filter_hosts", "tests": [{"args": [{"a": {"free_mb": 8192, "cores": 16, "nets": ["mgmt", "vlan10"]}, "b": {"free_mb": 2048, "cores": 16, "nets": ["mgmt", "vlan10", "vlan20"]}, "c": {"free_mb": 16384, "cores": 4, "nets": ["mgmt", "vlan10"]}, "d": {"free_mb": 16384, "cores": 16, "nets": ["mgmt"]}}, {"mem_mb": 4096, "vcpus": 8, "nets": ["mgmt"]}], "expected": ["a", "d"]}, {"args": [{"a": {"free_mb": 8192, "cores": 16, "nets": ["mgmt", "vlan10"]}, "b": {"free_mb": 2048, "cores": 16, "nets": ["mgmt", "vlan10", "vlan20"]}, "c": {"free_mb": 16384, "cores": 4, "nets": ["mgmt", "vlan10"]}, "d": {"free_mb": 16384, "cores": 16, "nets": ["mgmt"]}}, {"mem_mb": 4096, "vcpus": 8, "nets": ["mgmt", "vlan20"]}], "expected": []}, {"args": [{"a": {"free_mb": 8192, "cores": 16, "nets": ["mgmt", "vlan10"]}, "b": {"free_mb": 2048, "cores": 16, "nets": ["mgmt", "vlan10", "vlan20"]}, "c": {"free_mb": 16384, "cores": 4, "nets": ["mgmt", "vlan10"]}, "d": {"free_mb": 16384, "cores": 16, "nets": ["mgmt"]}}, {"mem_mb": 20000, "vcpus": 1, "nets": []}], "expected": []}, {"args": [{"a": {"free_mb": 8192, "cores": 16, "nets": ["mgmt", "vlan10"]}, "b": {"free_mb": 2048, "cores": 16, "nets": ["mgmt", "vlan10", "vlan20"]}, "c": {"free_mb": 16384, "cores": 4, "nets": ["mgmt", "vlan10"]}, "d": {"free_mb": 16384, "cores": 16, "nets": ["mgmt"]}}, {"mem_mb": 1024, "vcpus": 2, "nets": ["mgmt", "vlan10"]}], "expected": ["a", "b", "c"]}, {"args": [{"a": {"free_mb": 8192, "cores": 16, "nets": ["mgmt", "vlan10"]}, "b": {"free_mb": 2048, "cores": 16, "nets": ["mgmt", "vlan10", "vlan20"]}, "c": {"free_mb": 16384, "cores": 4, "nets": ["mgmt", "vlan10"]}, "d": {"free_mb": 16384, "cores": 16, "nets": ["mgmt"]}}, {"mem_mb": 2048, "vcpus": 16, "nets": ["mgmt", "vlan10"]}], "expected": ["a", "b"]}, {"args": [{}, {"mem_mb": 1, "vcpus": 1, "nets": []}], "expected": []}, {"args": [{"a": {"free_mb": 8192, "cores": 16, "nets": ["mgmt", "vlan10"]}, "b": {"free_mb": 2048, "cores": 16, "nets": ["mgmt", "vlan10", "vlan20"]}, "c": {"free_mb": 16384, "cores": 4, "nets": ["mgmt", "vlan10"]}, "d": {"free_mb": 16384, "cores": 16, "nets": ["mgmt"]}}, {"mem_mb": 8192, "vcpus": 16, "nets": ["vlan10"]}], "expected": ["a"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-schedule-host', 2, 'func', 'Выбор хоста: фильтры и веса', 'Реализуйте планировщик целиком. Сначала примените фильтры из прошлой задачи (память, ядра, сети) — у хоста те же поля free_mb, cores, nets, а ещё vms (число машин) и cpu (загрузка в процентах). Затем веса. Политика policy — список пар [модуль, коэффициент]. Каждый модуль задаёт ключ хоста: vm_count — vms, cpu_load — cpu, free_mem — минус free_mb (чем больше свободной памяти, тем лучше). Оценка хоста по модулю — его ранг среди оставшихся хостов: число оставшихся хостов со строго меньшим ключом (лучший получает 0, равные получают одинаковый ранг). Итог хоста — сумма коэффициент × ранг по всем модулям политики. Побеждает хост с наименьшим итогом, при равенстве — с меньшим именем. Напишите функцию schedule_host(hosts, vm, policy): верните имя хоста или пустую строку, если подходящих хостов нет. При пустой политике итоги все нули.', 'def schedule_host(hosts, vm, policy):
    pass
', 'Сначала отфильтруйте, потом для каждого модуля посчитайте ранг через sum(1 for m in ok if key(m) < key(n)) и накапливайте итог по хостам.', '{"func": "schedule_host", "tests": [{"args": [{"h1": {"free_mb": 8192, "cores": 8, "nets": ["m", "v"], "vms": 5, "cpu": 40}, "h2": {"free_mb": 16384, "cores": 8, "nets": ["m", "v"], "vms": 3, "cpu": 60}, "h3": {"free_mb": 4096, "cores": 8, "nets": ["m", "v"], "vms": 1, "cpu": 20}, "h4": {"free_mb": 32768, "cores": 2, "nets": ["m", "v"], "vms": 0, "cpu": 5}}, {"mem_mb": 2048, "vcpus": 4, "nets": ["m", "v"]}, [["vm_count", 1]]], "expected": "h3"}, {"args": [{"h1": {"free_mb": 8192, "cores": 8, "nets": ["m", "v"], "vms": 5, "cpu": 40}, "h2": {"free_mb": 16384, "cores": 8, "nets": ["m", "v"], "vms": 3, "cpu": 60}, "h3": {"free_mb": 4096, "cores": 8, "nets": ["m", "v"], "vms": 1, "cpu": 20}, "h4": {"free_mb": 32768, "cores": 2, "nets": ["m", "v"], "vms": 0, "cpu": 5}}, {"mem_mb": 2048, "vcpus": 4, "nets": ["m", "v"]}, [["cpu_load", 1], ["vm_count", 1]]], "expected": "h3"}, {"args": [{"h1": {"free_mb": 8192, "cores": 8, "nets": ["m", "v"], "vms": 5, "cpu": 40}, "h2": {"free_mb": 16384, "cores": 8, "nets": ["m", "v"], "vms": 3, "cpu": 60}, "h3": {"free_mb": 4096, "cores": 8, "nets": ["m", "v"], "vms": 1, "cpu": 20}, "h4": {"free_mb": 32768, "cores": 2, "nets": ["m", "v"], "vms": 0, "cpu": 5}}, {"mem_mb": 2048, "vcpus": 4, "nets": ["m", "v"]}, [["free_mem", 3], ["vm_count", 1]]], "expected": "h2"}, {"args": [{"h1": {"free_mb": 8192, "cores": 8, "nets": ["m", "v"], "vms": 5, "cpu": 40}, "h2": {"free_mb": 16384, "cores": 8, "nets": ["m", "v"], "vms": 3, "cpu": 60}, "h3": {"free_mb": 4096, "cores": 8, "nets": ["m", "v"], "vms": 1, "cpu": 20}, "h4": {"free_mb": 32768, "cores": 2, "nets": ["m", "v"], "vms": 0, "cpu": 5}}, {"mem_mb": 2048, "vcpus": 4, "nets": ["m", "v"]}, [["free_mem", 1], ["cpu_load", 1], ["vm_count", 1]]], "expected": "h3"}, {"args": [{"h1": {"free_mb": 8192, "cores": 8, "nets": ["m", "v"], "vms": 5, "cpu": 40}, "h2": {"free_mb": 16384, "cores": 8, "nets": ["m", "v"], "vms": 3, "cpu": 60}, "h3": {"free_mb": 4096, "cores": 8, "nets": ["m", "v"], "vms": 1, "cpu": 20}, "h4": {"free_mb": 32768, "cores": 2, "nets": ["m", "v"], "vms": 0, "cpu": 5}}, {"mem_mb": 2048, "vcpus": 4, "nets": ["m", "v"]}, []], "expected": "h1"}, {"args": [{"h1": {"free_mb": 8192, "cores": 8, "nets": ["m", "v"], "vms": 5, "cpu": 40}, "h2": {"free_mb": 16384, "cores": 8, "nets": ["m", "v"], "vms": 3, "cpu": 60}, "h3": {"free_mb": 4096, "cores": 8, "nets": ["m", "v"], "vms": 1, "cpu": 20}, "h4": {"free_mb": 32768, "cores": 2, "nets": ["m", "v"], "vms": 0, "cpu": 5}}, {"mem_mb": 99999, "vcpus": 1, "nets": ["m"]}, [["vm_count", 1]]], "expected": ""}, {"args": [{"h1": {"free_mb": 8192, "cores": 8, "nets": ["m", "v"], "vms": 5, "cpu": 40}, "h2": {"free_mb": 16384, "cores": 8, "nets": ["m", "v"], "vms": 3, "cpu": 60}, "h3": {"free_mb": 4096, "cores": 8, "nets": ["m", "v"], "vms": 1, "cpu": 20}, "h4": {"free_mb": 32768, "cores": 2, "nets": ["m", "v"], "vms": 0, "cpu": 5}}, {"mem_mb": 1024, "vcpus": 1, "nets": ["m"]}, [["cpu_load", 2], ["free_mem", 1]]], "expected": "h4"}, {"args": [{"h1": {"free_mb": 8192, "cores": 8, "nets": ["m", "v"], "vms": 5, "cpu": 40}, "h2": {"free_mb": 16384, "cores": 8, "nets": ["m", "v"], "vms": 3, "cpu": 60}, "h3": {"free_mb": 4096, "cores": 8, "nets": ["m", "v"], "vms": 1, "cpu": 20}, "h4": {"free_mb": 32768, "cores": 2, "nets": ["m", "v"], "vms": 0, "cpu": 5}}, {"mem_mb": 1024, "vcpus": 1, "nets": ["m"]}, [["free_mem", 2], ["cpu_load", 1]]], "expected": "h4"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-scheduling-memory', 3, 'func', 'Планировочная память хоста', 'Оптимизация памяти кластера задаёт множитель планировочной памяти: режим "none" — 100 процентов, "server" — 150, "desktop" — 200. Планировочная память хоста — это phys_mb × процент // 100 (целочисленное деление) минус reserved_mb минус сумма памяти всех работающих и запускающихся машин running_mb (список чисел). Напишите функцию scheduling_free(phys_mb, mode, reserved_mb, running_mb): верните остаток (он может быть отрицательным, если хост уже перегружен).', 'def scheduling_free(phys_mb, mode, reserved_mb, running_mb):
    pass
', 'Словарь режим → процент, затем одна формула.', '{"func": "scheduling_free", "tests": [{"args": [65536, "none", 0, []], "expected": 65536}, {"args": [65536, "server", 0, [30000, 40000]], "expected": 28304}, {"args": [65536, "server", 1024, [30000, 40000]], "expected": 27280}, {"args": [65536, "desktop", 2048, [100000]], "expected": 29024}, {"args": [65536, "desktop", 2048, [100000, 40000]], "expected": -10976}, {"args": [1001, "server", 0, []], "expected": 1501}, {"args": [32768, "none", 512, [8192, 8192, 8192]], "expected": 7680}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-balancer-step', 4, 'func', 'Шаг балансировщика', 'Балансировщик за один проход переносит не больше одной машины. Хосты: hosts — словарь имя → {"cpu": загрузка в процентах, "vms": {имя машины: вклад машины в загрузку в процентных пунктах}}; high — порог перегрузки; pinned — список имён машин, которые мигрировать нельзя. Правила. Перегруженным считается хост с cpu строго больше high; если таких нет, верните None. Источник — самый загруженный из перегруженных (при равенстве меньшее имя). Приёмник — наименее загруженный из остальных хостов (при равенстве меньшее имя); других хостов нет — None. Кандидаты — машины источника, не из pinned, для которых cpu приёмника плюс вклад машины не больше high. Из кандидатов выберите машину с наибольшим вкладом (при равенстве меньшее имя); кандидатов нет — None. Напишите функцию pick_balancing_vm(hosts, high, pinned): верните кортеж (машина, источник, приёмник) или None.', 'def pick_balancing_vm(hosts, high, pinned):
    pass
', 'Разбейте на шаги: перегруженные, источник, приёмник, кандидаты, выбор по ключу (-вклад, имя).', '{"func": "pick_balancing_vm", "tests": [{"args": [{"n1": {"cpu": 90, "vms": {"a": 30, "b": 25, "c": 10}}, "n2": {"cpu": 50, "vms": {"d": 20, "e": 30}}, "n3": {"cpu": 60, "vms": {"f": 60}}}, 80, []], "expected": {"__tuple__": ["a", "n1", "n2"]}}, {"args": [{"n1": {"cpu": 90, "vms": {"a": 30, "b": 25, "c": 10}}, "n2": {"cpu": 50, "vms": {"d": 20, "e": 30}}, "n3": {"cpu": 60, "vms": {"f": 60}}}, 80, ["a"]], "expected": {"__tuple__": ["b", "n1", "n2"]}}, {"args": [{"n1": {"cpu": 90, "vms": {"a": 30, "b": 25, "c": 10}}, "n2": {"cpu": 50, "vms": {"d": 20, "e": 30}}, "n3": {"cpu": 60, "vms": {"f": 60}}}, 80, ["a", "b"]], "expected": {"__tuple__": ["c", "n1", "n2"]}}, {"args": [{"n1": {"cpu": 90, "vms": {"a": 30, "b": 25, "c": 10}}, "n2": {"cpu": 50, "vms": {"d": 20, "e": 30}}, "n3": {"cpu": 60, "vms": {"f": 60}}}, 95, []], "expected": null}, {"args": [{"n1": {"cpu": 90, "vms": {"a": 30, "b": 25, "c": 10}}, "n2": {"cpu": 50, "vms": {"d": 20, "e": 30}}, "n3": {"cpu": 60, "vms": {"f": 60}}}, 70, []], "expected": {"__tuple__": ["c", "n1", "n2"]}}, {"args": [{"only": {"cpu": 99, "vms": {"x": 99}}}, 80, []], "expected": null}, {"args": [{"p": {"cpu": 85, "vms": {"x": 20, "y": 20}}, "q": {"cpu": 60, "vms": {}}, "r": {"cpu": 60, "vms": {}}}, 80, []], "expected": {"__tuple__": ["x", "p", "q"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-affinity-check', 5, 'func', 'Проверка групп соответствия', 'Дано размещение placement — словарь машина → хост (машин, которые не запущены, в нём нет) и список групп groups; группа — {"vms": список машин, "positive": bool, "enforcing": bool}. Положительная группа нарушена, если запущенные машины группы стоят более чем на одном хосте. Отрицательная нарушена, если хотя бы две запущенные машины группы стоят на одном хосте. Незапущенные машины группы игнорируются. Напишите функцию affinity_violations(groups, placement): верните кортеж из двух списков номеров групп (с нуля, по возрастанию): сначала нарушенные жёсткие группы (enforcing), затем нарушенные мягкие.', 'def affinity_violations(groups, placement):
    pass
', 'where = [placement[v] for v in g[''vms''] if v in placement]; положительная нарушена при len(set(where)) > 1, отрицательная при len(set(where)) < len(where).', '{"func": "affinity_violations", "tests": [{"args": [[{"vms": ["web1", "web2"], "positive": false, "enforcing": true}, {"vms": ["app", "cache"], "positive": true, "enforcing": true}, {"vms": ["db1", "db2", "db3"], "positive": false, "enforcing": false}, {"vms": ["log", "mon"], "positive": true, "enforcing": false}], {"web1": "h1", "web2": "h2", "app": "h1", "cache": "h1", "db1": "h1", "db2": "h2", "db3": "h3", "log": "h1", "mon": "h1"}], "expected": {"__tuple__": [[], []]}}, {"args": [[{"vms": ["web1", "web2"], "positive": false, "enforcing": true}, {"vms": ["app", "cache"], "positive": true, "enforcing": true}, {"vms": ["db1", "db2", "db3"], "positive": false, "enforcing": false}, {"vms": ["log", "mon"], "positive": true, "enforcing": false}], {"web1": "h1", "web2": "h1", "app": "h1", "cache": "h2"}], "expected": {"__tuple__": [[0, 1], []]}}, {"args": [[{"vms": ["web1", "web2"], "positive": false, "enforcing": true}, {"vms": ["app", "cache"], "positive": true, "enforcing": true}, {"vms": ["db1", "db2", "db3"], "positive": false, "enforcing": false}, {"vms": ["log", "mon"], "positive": true, "enforcing": false}], {"db1": "h1", "db2": "h1", "db3": "h1", "log": "h1", "mon": "h2"}], "expected": {"__tuple__": [[], [2, 3]]}}, {"args": [[{"vms": ["web1", "web2"], "positive": false, "enforcing": true}, {"vms": ["app", "cache"], "positive": true, "enforcing": true}, {"vms": ["db1", "db2", "db3"], "positive": false, "enforcing": false}, {"vms": ["log", "mon"], "positive": true, "enforcing": false}], {}], "expected": {"__tuple__": [[], []]}}, {"args": [[{"vms": ["web1", "web2"], "positive": false, "enforcing": true}, {"vms": ["app", "cache"], "positive": true, "enforcing": true}, {"vms": ["db1", "db2", "db3"], "positive": false, "enforcing": false}, {"vms": ["log", "mon"], "positive": true, "enforcing": false}], {"web1": "h1", "app": "h2", "db1": "h3", "log": "h9"}], "expected": {"__tuple__": [[], []]}}, {"args": [[], {"a": "h1"}], "expected": {"__tuple__": [[], []]}}, {"args": [[{"vms": ["web1", "web2"], "positive": false, "enforcing": true}, {"vms": ["app", "cache"], "positive": true, "enforcing": true}, {"vms": ["db1", "db2", "db3"], "positive": false, "enforcing": false}, {"vms": ["log", "mon"], "positive": true, "enforcing": false}], {"web1": "h1", "web2": "h1", "app": "h1", "cache": "h2", "db1": "h1", "db2": "h1", "log": "h1", "mon": "h2"}], "expected": {"__tuple__": [[0, 1], [2, 3]]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-affinity-place', 6, 'func', 'Размещение с жёсткими группами', 'Найдите размещение машин, которое удовлетворяет всем жёстким группам. Даны vms — список имён машин в порядке размещения, hosts — список пар (имя хоста, вместимость в машинах) в порядке перебора и groups — группы {"vms": [...], "positive": bool, "enforcing": bool}; мягкие группы (enforcing равно False) игнорируйте. Положительная жёсткая группа требует, чтобы все её размещённые машины стояли на одном хосте, отрицательная — чтобы никакие две не стояли на одном. Число машин на хосте не больше его вместимости. Машины групп, которых нет в vms, не учитываются. Напишите функцию place_vms(vms, hosts, groups): верните список хостов, параллельный vms, который при размещении машин по порядку и переборе хостов по порядку оказывается первым найденным (лексикографически наименьшим по порядку хостов); если решения нет, верните None. Потребуется перебор с откатом.', 'def place_vms(vms, hosts, groups):
    pass
', 'Рекурсия по номеру машины: для каждого хоста по порядку проверьте вместимость и группы по уже размещённым машинам, поставьте, углубитесь, при неудаче откатите.', '{"func": "place_vms", "tests": [{"args": [["a", "b", "c"], [["h1", 2], ["h2", 2]], [{"vms": ["b", "c"], "positive": false, "enforcing": true}, {"vms": ["a", "c"], "positive": true, "enforcing": true}]], "expected": ["h1", "h2", "h1"]}, {"args": [["a", "b"], [["h1", 1], ["h2", 1]], []], "expected": ["h1", "h2"]}, {"args": [["a", "b", "c"], [["h1", 1], ["h2", 1]], []], "expected": null}, {"args": [["a", "b"], [["h1", 2]], [{"vms": ["a", "b"], "positive": false, "enforcing": true}]], "expected": null}, {"args": [["a", "b"], [["h1", 2], ["h2", 2]], [{"vms": ["a", "b"], "positive": false, "enforcing": false}]], "expected": ["h1", "h1"]}, {"args": [["a", "b", "c", "d"], [["h1", 2], ["h2", 2], ["h3", 2]], [{"vms": ["a", "b", "c"], "positive": false, "enforcing": true}, {"vms": ["c", "d"], "positive": true, "enforcing": true}, {"vms": ["a", "d"], "positive": false, "enforcing": true}]], "expected": ["h1", "h2", "h3", "h3"]}, {"args": [["x", "y", "z"], [["h1", 3]], [{"vms": ["x", "y"], "positive": true, "enforcing": true}, {"vms": ["y", "q"], "positive": false, "enforcing": true}]], "expected": ["h1", "h1", "h1"]}, {"args": [[], [["h1", 1]], []], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-ha-restart', 7, 'func', 'Перезапуск HA после отказа хоста', 'Хост отказал, нужно перезапустить его высокодоступные машины. vms — список кортежей (имя, приоритет, память_мб, ha): приоритет — число (низкий 1, средний 50, высокий 100), ha — bool; free — словарь живой хост → свободная память в МБ. Машины без ha не перезапускаются. Остальные обрабатываются по порядку: приоритет по убыванию, при равенстве имя по возрастанию. Каждая машина идёт на хост с наибольшей свободной памятью (при равенстве меньшее имя), если памяти хватает (free не меньше памяти машины); свободная память хоста при этом уменьшается. Иначе машина не перезапущена, и обработка продолжается со следующей (меньшая машина после неудачи ещё может уместиться). Напишите функцию ha_restart(vms, free): верните кортеж (restarted, failed): restarted — список пар (машина, хост) в порядке обработки, failed — список имён неперезапущенных машин в порядке обработки. Если живых хостов нет, все HA-машины попадают в failed.', 'def ha_restart(vms, free):
    pass
', 'Отсортируйте HA-машины по (-приоритет, имя); для каждой возьмите хост max по (свободная память, обратное имя) — удобно sorted(free, key=lambda h: (-free[h], h))[0].', '{"func": "ha_restart", "tests": [{"args": [[{"__tuple__": ["db", 100, 8000, true]}, {"__tuple__": ["web", 50, 4000, true]}, {"__tuple__": ["test", 1, 2000, false]}], {"h1": 16000, "h2": 9000}], "expected": {"__tuple__": [[{"__tuple__": ["db", "h1"]}, {"__tuple__": ["web", "h2"]}], []]}}, {"args": [[{"__tuple__": ["a", 50, 6000, true]}, {"__tuple__": ["b", 100, 6000, true]}, {"__tuple__": ["c", 1, 1000, true]}], {"h1": 7000, "h2": 6500}], "expected": {"__tuple__": [[{"__tuple__": ["b", "h1"]}, {"__tuple__": ["a", "h2"]}, {"__tuple__": ["c", "h1"]}], []]}}, {"args": [[{"__tuple__": ["big", 100, 10000, true]}, {"__tuple__": ["small", 50, 1000, true]}], {"h1": 5000}], "expected": {"__tuple__": [[{"__tuple__": ["small", "h1"]}], ["big"]]}}, {"args": [[{"__tuple__": ["x", 50, 1000, true]}, {"__tuple__": ["y", 50, 1000, true]}, {"__tuple__": ["z", 50, 1000, true]}], {"h1": 2000, "h2": 1500}], "expected": {"__tuple__": [[{"__tuple__": ["x", "h1"]}, {"__tuple__": ["y", "h2"]}, {"__tuple__": ["z", "h1"]}], []]}}, {"args": [[{"__tuple__": ["a", 100, 1000, true]}], {}], "expected": {"__tuple__": [[], ["a"]]}}, {"args": [[], {"h1": 1}], "expected": {"__tuple__": [[], []]}}, {"args": [[{"__tuple__": ["m", 1, 4000, true]}, {"__tuple__": ["n", 100, 3000, true]}, {"__tuple__": ["o", 100, 5000, true]}], {"b": 5000, "a": 5000}], "expected": {"__tuple__": [[{"__tuple__": ["n", "a"]}, {"__tuple__": ["o", "b"]}], ["m"]]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-precopy', 8, 'func', 'Симуляция предкопирования', 'Смоделируйте живую миграцию. Память ВМ — mem_mb МБ, скорость записи гостя — dirty_mbs МБ/с, пропускная способность — bw_mbs МБ/с, допустимый простой — max_downtime_ms миллисекунд, предел проходов — max_rounds. Проход i (i от 1 до max_rounds) отправляет текущий остаток remaining (в проходе 1 он равен mem_mb) за remaining / bw_mbs секунд; за это время гость успевает загрязнить min(mem_mb, dirty_mbs × время) МБ — это новый остаток. Если после прохода время отправки нового остатка (остаток / bw_mbs секунд) не больше max_downtime_ms, миграция завершается остановкой: остаток досылается, простой равен его времени отправки. Если за max_rounds проходов условие так и не выполнилось, миграция провалена. Напишите функцию precopy(mem_mb, dirty_mbs, bw_mbs, max_downtime_ms, max_rounds): верните кортеж ("done", номер_прохода, простой_мс, общее_время_мс) или ("failed", max_rounds, 0, общее_время_мс), где общее время — сумма времён всех проходов (и последней досылки в случае успеха) в миллисекундах; оба времени округляйте функцией round до целых. Используйте дроби (модуль fractions), чтобы не накапливать ошибку.', 'def precopy(mem_mb, dirty_mbs, bw_mbs, max_downtime_ms, max_rounds):
    pass
', 'Храните остаток и общее время как Fraction. В цикле: dur = remaining / bw; total += dur; remaining = min(mem, dirty * dur); проверьте остаток / bw * 1000 <= max_downtime_ms.', '{"func": "precopy", "tests": [{"args": [8000, 100, 1000, 300, 10], "expected": {"__tuple__": ["done", 2, 80, 8880]}}, {"args": [8000, 0, 1000, 300, 10], "expected": {"__tuple__": ["done", 1, 0, 8000]}}, {"args": [8000, 2000, 1000, 300, 10], "expected": {"__tuple__": ["failed", 10, 0, 80000]}}, {"args": [8000, 1000, 1000, 300, 10], "expected": {"__tuple__": ["failed", 10, 0, 80000]}}, {"args": [4096, 500, 1000, 50, 5], "expected": {"__tuple__": ["failed", 5, 0, 7936]}}, {"args": [4096, 500, 1000, 50, 3], "expected": {"__tuple__": ["failed", 3, 0, 7168]}}, {"args": [1000, 100, 1000, 100, 1], "expected": {"__tuple__": ["done", 1, 100, 1100]}}, {"args": [2000, 400, 1000, 200, 20], "expected": {"__tuple__": ["done", 3, 128, 3248]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-migration-policy', 9, 'func', 'Ступени простоя политики миграции', 'Смоделируйте политику миграции по итерациям кьюму. times — список времён в миллисекундах, нужных для досылки остатка на каждой итерации (индексы с нуля). Допустимый простой limit начинается со 100. На итерации i сначала проверяется буксование: если i больше 0 и times[i] не меньше times[i-1], счётчик stalls растёт на единицу. При stalls от 1 до 6 limit становится: 1 → 150, 2 → 200, 3 → 300, 4 и 5 → 400, 6 → 500. Когда stalls равен 7, поведение зависит от политики policy: "minimal" — миграция отменяется, "postcopy" — переключается на post-copy, "suspend" — limit становится 5000. Когда stalls достигает 8 (возможно только у "suspend"), миграция отменяется. Отмена и переключение происходят сразу, до проверки завершения. Если не отменена, то после этого проверяется завершение: times[i] не больше limit. Напишите функцию migration_outcome(policy, times): верните ("done", i, times[i]) на первой итерации, где миграция завершилась; ("aborted", i) при отмене; ("postcopy", i) при переключении; а если список закончился ни на чём из этого — ("running", len(times)).', 'def migration_outcome(policy, times):
    pass
', 'Храните limit и stalls между итерациями; ступени удобно держать списком пар (stalls, limit) и брать последнюю подходящую.', '{"func": "migration_outcome", "tests": [{"args": ["minimal", [900, 400, 90]], "expected": {"__tuple__": ["done", 2, 90]}}, {"args": ["minimal", [900, 400, 120]], "expected": {"__tuple__": ["running", 3]}}, {"args": ["minimal", [500, 500, 500, 500, 500, 500, 500, 500]], "expected": {"__tuple__": ["done", 6, 500]}}, {"args": ["minimal", [1000, 1100, 1200, 1300, 1400, 1500, 1600, 1700]], "expected": {"__tuple__": ["aborted", 7]}}, {"args": ["postcopy", [1000, 1100, 1200, 1300, 1400, 1500, 1600, 1700, 1800]], "expected": {"__tuple__": ["postcopy", 7]}}, {"args": ["suspend", [1000, 1100, 1200, 1300, 1400, 1500, 1600, 1700, 1800]], "expected": {"__tuple__": ["done", 7, 1700]}}, {"args": ["suspend", [9000, 9000, 9000, 9000, 9000, 9000, 9000, 9000, 9000]], "expected": {"__tuple__": ["aborted", 8]}}, {"args": ["suspend", [9000, 9000, 9000, 9000, 9000, 9000, 4000]], "expected": {"__tuple__": ["running", 7]}}, {"args": ["minimal", []], "expected": {"__tuple__": ["running", 0]}}, {"args": ["minimal", [150, 140]], "expected": {"__tuple__": ["running", 2]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-migration-log', 10, 'func', 'Разбор журнала миграций', 'Журнал событий менеджера содержит строки вида "2026-01-05 10:01:02 migration vm=web src=h1 dst=h2 state=started". Первые два слова — дата и время, третье слово — тип события, дальше пары ключ=значение в любом порядке. Для завершённой миграции есть ещё duration=секунды, для неудачной — reason=текст. Обрабатываются только строки, у которых третье слово равно migration и есть ключи vm и state; остальные пропустите. Напишите функцию migration_log(lines): верните словарь машина → кортеж (последнее_состояние, число_попыток, секунды). Число попыток — сколько событий state=started было у машины; секунды — значение duration последнего события, если его состояние completed, иначе 0. Строки идут в хронологическом порядке.', 'def migration_log(lines):
    pass
', 'line.split(); parts[2] == ''migration''; пары: dict(p.split(''='', 1) for p in parts[3:] if ''='' in p).', '{"func": "migration_log", "tests": [{"args": [["2026-01-05 10:01:02 migration vm=web src=h1 dst=h2 state=started", "2026-01-05 10:01:40 migration vm=web src=h1 dst=h2 state=completed duration=38"]], "expected": {"web": {"__tuple__": ["completed", 1, 38]}}}, {"args": [["2026-01-05 10:01:02 migration vm=db src=h1 dst=h2 state=started", "2026-01-05 10:03:02 migration vm=db src=h1 dst=h2 state=failed reason=timeout", "2026-01-05 10:05:00 migration vm=db src=h1 dst=h3 state=started", "2026-01-05 10:05:50 migration vm=db src=h1 dst=h3 state=completed duration=50"]], "expected": {"db": {"__tuple__": ["completed", 2, 50]}}}, {"args": [[]], "expected": {}}, {"args": [["2026-01-05 10:01:02 start vm=web state=ok", "2026-01-05 10:01:03 migration src=h1 dst=h2 state=started", "bad", "2026-01-05 10:01:04 migration vm=web state=started src=h1"]], "expected": {"web": {"__tuple__": ["started", 1, 0]}}}, {"args": [["2026-01-05 10:01:02 migration state=started vm=a dst=h2 src=h1", "2026-01-05 10:01:03 migration vm=b src=h1 dst=h2 state=started", "2026-01-05 10:01:30 migration duration=25 vm=a state=completed", "2026-01-05 10:02:00 migration vm=b state=failed reason=no progress"]], "expected": {"a": {"__tuple__": ["completed", 1, 25]}, "b": {"__tuple__": ["failed", 1, 0]}}}, {"args": [["2026-01-05 10:01:02 migration vm=x state=started", "2026-01-05 10:01:05 migration vm=x state=started", "2026-01-05 10:01:09 migration vm=x state=started"]], "expected": {"x": {"__tuple__": ["started", 3, 0]}}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-resilience-order', 11, 'func', 'Политика устойчивости кластера', 'Хост стал неработоспособным. Политика устойчивости policy бывает такой: "migrate_all" — мигрировать все машины, "migrate_ha" — только высокодоступные, "do_not_migrate" — никакие. vms — список кортежей (имя, ha, приоритет), где ha — bool, приоритет — число. Напишите функцию resilience_order(policy, vms): верните список имён машин, которые нужно мигрировать, в порядке миграции: по убыванию приоритета, при равенстве по имени.', 'def resilience_order(policy, vms):
    pass
', 'Сначала отберите машины по политике, потом sorted с ключом (-приоритет, имя).', '{"func": "resilience_order", "tests": [{"args": ["migrate_all", [{"__tuple__": ["a", false, 1]}, {"__tuple__": ["b", true, 100]}, {"__tuple__": ["c", true, 50]}, {"__tuple__": ["d", false, 100]}]], "expected": ["b", "d", "c", "a"]}, {"args": ["migrate_ha", [{"__tuple__": ["a", false, 1]}, {"__tuple__": ["b", true, 100]}, {"__tuple__": ["c", true, 50]}, {"__tuple__": ["d", false, 100]}]], "expected": ["b", "c"]}, {"args": ["do_not_migrate", [{"__tuple__": ["a", true, 100]}]], "expected": []}, {"args": ["migrate_all", []], "expected": []}, {"args": ["migrate_ha", [{"__tuple__": ["x", false, 5]}]], "expected": []}, {"args": ["migrate_ha", [{"__tuple__": ["m", true, 50]}, {"__tuple__": ["k", true, 50]}, {"__tuple__": ["z", true, 1]}]], "expected": ["k", "m", "z"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-migration-queue', 12, 'func', 'Очередь миграций и полоса', 'Хост выпускает одновременно не более max_parallel миграций, остальные ждут. Полоса total задаётся режимом mode: "manual" — число custom_mbps; "auto" — наименьшая скорость из списка links_mbps (если список пуст, как у режима по умолчанию); любой другой режим ("default") — 256 Мбит/с. Каждая миграция получает постоянную долю per = max(total // max_parallel, 1) Мбит/с, независимо от числа одновременно работающих. Миграция машины памятью mem_mb МБ занимает ceil(mem_mb × 8 / per) секунд (деление нацело с округлением вверх). Миграции из списка vms (кортежи (имя, mem_mb)) берутся строго по порядку; каждая стартует на слоте, освободившемся раньше всех (при равенстве слот с меньшим номером), и слоты в начале свободны с секунды 0. Напишите функцию migration_finish_times(vms, mode, links_mbps, custom_mbps, max_parallel): верните словарь имя → секунда завершения.', 'def migration_finish_times(vms, mode, links_mbps, custom_mbps, max_parallel):
    pass
', 'Список slots из max_parallel нулей — моменты освобождения слотов. Для каждой миграции берите слот с минимальным (время, номер) и прибавляйте длительность.', '{"func": "migration_finish_times", "tests": [{"args": [[{"__tuple__": ["a", 1000]}, {"__tuple__": ["b", 2000]}], "manual", [], 2000, 2], "expected": {"a": 8, "b": 16}}, {"args": [[{"__tuple__": ["a", 1000]}, {"__tuple__": ["b", 2000]}, {"__tuple__": ["c", 500]}], "manual", [], 2000, 2], "expected": {"a": 8, "b": 16, "c": 12}}, {"args": [[{"__tuple__": ["a", 100]}, {"__tuple__": ["b", 100]}], "default", [], 0, 1], "expected": {"a": 4, "b": 8}}, {"args": [[{"__tuple__": ["a", 100]}, {"__tuple__": ["b", 100]}], "auto", [10000, 1000, 2500], 0, 2], "expected": {"a": 2, "b": 2}}, {"args": [[{"__tuple__": ["a", 100]}], "auto", [], 0, 2], "expected": {"a": 7}}, {"args": [[{"__tuple__": ["a", 333]}, {"__tuple__": ["b", 1]}, {"__tuple__": ["c", 1000]}, {"__tuple__": ["d", 77]}], "manual", [], 1000, 3], "expected": {"a": 8, "b": 1, "c": 25, "d": 3}}, {"args": [[], "manual", [], 100, 2], "expected": {}}, {"args": [[{"__tuple__": ["a", 10]}], "manual", [], 1, 4], "expected": {"a": 80}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-numa-assign', 13, 'func', 'Раскладка виртуальных узлов NUMA', 'У хоста есть узлы NUMA с оставшимися ресурсами host_nodes — список пар (ядра, память_гб). У машины виртуальные узлы vnodes — тоже список пар (ядра, память_гб). Каждый виртуальный узел целиком кладётся на один узел хоста, где хватает и ядер, и памяти; на один узел хоста можно положить несколько виртуальных, пока хватает ресурсов. Напишите функцию numa_assign(vnodes, host_nodes): верните список номеров узлов хоста, параллельный vnodes, — первый найденный перебором с откатом (виртуальные узлы по порядку, узлы хоста по порядку номеров); если разместить нельзя, верните None. Для пустого vnodes верните пустой список.', 'def numa_assign(vnodes, host_nodes):
    pass
', 'Рекурсия по номеру виртуального узла; на каждом шаге пробуйте узлы хоста по порядку, вычитайте ресурсы и откатывайте при неудаче.', '{"func": "numa_assign", "tests": [{"args": [[{"__tuple__": [4, 16]}, {"__tuple__": [4, 16]}], [{"__tuple__": [8, 32]}, {"__tuple__": [8, 32]}]], "expected": [0, 0]}, {"args": [[{"__tuple__": [4, 16]}, {"__tuple__": [4, 16]}], [{"__tuple__": [4, 16]}, {"__tuple__": [4, 16]}]], "expected": [0, 1]}, {"args": [[{"__tuple__": [2, 4]}, {"__tuple__": [6, 4]}, {"__tuple__": [2, 4]}], [{"__tuple__": [8, 8]}, {"__tuple__": [4, 4]}]], "expected": [0, 0, 1]}, {"args": [[{"__tuple__": [6, 10]}, {"__tuple__": [6, 10]}], [{"__tuple__": [8, 16]}, {"__tuple__": [4, 8]}]], "expected": null}, {"args": [[{"__tuple__": [2, 8]}, {"__tuple__": [2, 8]}, {"__tuple__": [4, 8]}], [{"__tuple__": [4, 16]}, {"__tuple__": [4, 8]}]], "expected": [0, 0, 1]}, {"args": [[{"__tuple__": [1, 1]}], []], "expected": null}, {"args": [[], [{"__tuple__": [1, 1]}]], "expected": []}, {"args": [[{"__tuple__": [4, 4]}, {"__tuple__": [4, 4]}, {"__tuple__": [4, 4]}], [{"__tuple__": [4, 4]}, {"__tuple__": [4, 4]}]], "expected": null}, {"args": [[{"__tuple__": [2, 2]}, {"__tuple__": [4, 4]}], [{"__tuple__": [4, 4]}, {"__tuple__": [2, 2]}]], "expected": [1, 0]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 22, 'ov22-cpu-shares', 14, 'func', 'Доли и потолки процессора', 'При нехватке процессора время делится пропорционально долям (CPU shares), а потолок QoS ограничивает потребление машины. total — всего процессорного времени (число, например в процентах одного ядра), vms — словарь имя → (доли, потолок), потолок — число или None (без ограничения). Алгоритм: пока есть неназначенные машины, посчитайте долю каждой как остаток × её доли / сумма долей неназначенных; машины, чья доля строго больше потолка, получают ровно потолок (одновременно все такие), остаток уменьшается на выданное, и повторите; если превышающих нет, все неназначенные получают свои доли и алгоритм заканчивается. Недоиспользованное время, если все машины упёрлись в потолки, просто остаётся неиспользованным. Напишите функцию cpu_allocation(total, vms): верните словарь имя → выделенное время (float, округлено round(x, 2)).', 'def cpu_allocation(total, vms):
    pass
', 'Цикл while active: посчитайте кандидатов на потолок; если их нет, раздайте остаток пропорционально и выйдите; иначе зафиксируйте потолки и вычтите их из остатка.', '{"func": "cpu_allocation", "tests": [{"args": [100, {"a": {"__tuple__": [1024, null]}, "b": {"__tuple__": [512, null]}, "c": {"__tuple__": [512, null]}}], "expected": {"a": 50.0, "b": 25.0, "c": 25.0}}, {"args": [100, {"a": {"__tuple__": [1024, 30]}, "b": {"__tuple__": [512, null]}, "c": {"__tuple__": [512, null]}}], "expected": {"a": 30.0, "b": 35.0, "c": 35.0}}, {"args": [100, {"a": {"__tuple__": [1, 10]}, "b": {"__tuple__": [1, 10]}, "c": {"__tuple__": [1, null]}}], "expected": {"a": 10.0, "b": 10.0, "c": 80.0}}, {"args": [100, {"a": {"__tuple__": [1, 10]}, "b": {"__tuple__": [1, 20]}}], "expected": {"a": 10.0, "b": 20.0}}, {"args": [90, {"a": {"__tuple__": [2048, 80]}, "b": {"__tuple__": [1024, 20]}, "c": {"__tuple__": [1024, null]}}], "expected": {"a": 46.67, "b": 20.0, "c": 23.33}}, {"args": [100, {}], "expected": {}}, {"args": [100, {"x": {"__tuple__": [5, null]}}], "expected": {"x": 100.0}}, {"args": [100, {"a": {"__tuple__": [1, 60]}, "b": {"__tuple__": [2, 15]}, "c": {"__tuple__": [1, 15]}}], "expected": {"a": 60.0, "b": 15.0, "c": 15.0}}]}');
